mapper.select:
SELECT FROM historical_places p LEFT JOIN regions r ON r.region_id = p.region_id
AND ( p.title LIKE CONCAT('%', #{keyword}, '%') OR p.address LIKE CONCAT('%', #{keyword}, '%') OR p.description LIKE CONCAT('%', #{keyword}, '%') OR p.period LIKE CONCAT('%', #{keyword}, '%') OR p.heritage_type LIKE CONCAT('%', #{keyword}, '%') )
AND r.sido_name = #{sidoName}
AND r.gugun_name = #{gugunName}
ORDER BY p.place_id LIMIT #{limit} OFFSET #{offset}
